import sys
import atheris


def TestOneInput(data: bytes) -> None:
    """Fuzz target for Mini-SGL's parsing and serialization functions."""
    import msgpack
    from dataclasses import dataclass

    # Import the targetted functions
    sys.path.insert(0, "/app/minisgl/python")
    from minisgl.tokenizer.detokenize import find_printable_text, _is_chinese_char
    from minisgl.message.utils import deserialize_type, serialize_type, _serialize_any

    fdp = atheris.FuzzedDataProvider(data)

    choice = fdp.ConsumeIntInRange(0, 3)

    if choice == 0:
        # Fuzz find_printable_text()
        text = fdp.ConsumeUnicode(fdp.remaining_bytes())
        try:
            find_printable_text(text)
        except (ValueError, IndexError, UnicodeDecodeError, OverflowError):
            pass

    elif choice == 1:
        # Fuzz _is_chinese_char() with various codepoints
        cp = fdp.ConsumeIntInRange(0, 0x10FFFF)
        try:
            _is_chinese_char(cp)
        except (ValueError, OverflowError):
            pass

    elif choice == 2:
        # Fuzz deserialize_type() with arbitrary dict data
        # Create a simple dataclass for testing
        @dataclass
        class TestMsg:
            uid: int = 0
            text: str = ""

        cls_map = {"TestMsg": TestMsg}

        # Build a dict that mimics serialized data
        type_name = fdp.ConsumeUnicode(64)
        remaining = fdp.ConsumeUnicode(fdp.remaining_bytes())

        test_data = {
            "__type__": type_name,
            "uid": fdp.ConsumeIntInRange(-1000000, 1000000) if fdp.remaining_bytes() > 4 else 0,
            "text": remaining,
        }

        try:
            deserialize_type(cls_map, test_data)
        except (KeyError, TypeError, ValueError, AttributeError,
                OverflowError, AssertionError):
            pass

    elif choice == 3:
        # Fuzz msgpack deserialization (the IPC transport layer)
        raw_bytes = fdp.ConsumeBytes(fdp.remaining_bytes())
        try:
            unpacked = msgpack.unpackb(raw_bytes, raw=False)
        except (msgpack.UnpackValueError, msgpack.FormatError,
                msgpack.StackError, ValueError, TypeError,
                msgpack.ExtraData):
            pass


def main():
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

"""Coverage-guided fuzz driver for the ujson (UltraJSON) library."""

import sys
import atheris


def TestOneInput(data: bytes) -> None:
    """Fuzz target for ujson's JSON parsing and encoding."""
    import ujson

    fdp = atheris.FuzzedDataProvider(data)

    choice = fdp.ConsumeIntInRange(0, 3)

    if choice == 0:
        # Fuzz ujson.loads() with string input
        json_str = fdp.ConsumeUnicode(fdp.remaining_bytes())
        if not json_str:
            return
        try:
            ujson.loads(json_str)
        except (ujson.JSONDecodeError, ValueError, OverflowError,
                RecursionError, MemoryError):
            pass

    elif choice == 1:
        # Fuzz ujson.loads() with bytes input
        json_bytes = fdp.ConsumeBytes(fdp.remaining_bytes())
        if not json_bytes:
            return
        try:
            ujson.loads(json_bytes)
        except (ujson.JSONDecodeError, ValueError, OverflowError,
                RecursionError, MemoryError, UnicodeDecodeError):
            pass

    elif choice == 2:
        # Fuzz ujson.dumps() with parsed objects, then roundtrip
        json_str = fdp.ConsumeUnicode(fdp.remaining_bytes())
        if not json_str:
            return
        try:
            obj = ujson.loads(json_str)
            encoded = ujson.dumps(obj)
            ujson.loads(encoded)
        except (ujson.JSONDecodeError, ValueError, OverflowError,
                RecursionError, MemoryError, TypeError):
            pass

    elif choice == 3:
        # Fuzz ujson.dumps() with various encoding options
        json_str = fdp.ConsumeUnicode(fdp.remaining_bytes())
        if not json_str:
            return
        try:
            obj = ujson.loads(json_str)
            # Test with different options
            ujson.dumps(obj, ensure_ascii=fdp.ConsumeBool() if fdp.remaining_bytes() > 0 else True)
            ujson.dumps(obj, sort_keys=True)
            ujson.dumps(obj, indent=2)
            ujson.dumps(obj, encode_html_chars=True)
            ujson.dumps(obj, escape_forward_slashes=False)
        except (ujson.JSONDecodeError, ValueError, OverflowError,
                RecursionError, MemoryError, TypeError):
            pass


def main():
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

